import numpy as np
def _ordering_metrics(s, output):
    p=np.asarray(output);n=len(s)
    if p.shape!=(n,) or not np.all(np.isfinite(p)) or not np.all(p==np.rint(p)):
        return np.array([0.,-1.,0.])
    p=p.astype(int)
    if not np.array_equal(np.sort(p),np.arange(n)):
        return np.array([0.,-1.,0.])
    pairs=[tuple(p[i:i+2]) for i in range(0,n,2)]
    if any(a>=b for a,b in pairs):return np.array([0.,-1.,0.])
    ordered=sorted(pairs);m=len(ordered);adj=[set() for _ in range(m)]
    for i in range(m):
        for j in range(i+1,m):
            if np.any(s[np.ix_(ordered[i],ordered[j])]!=0):adj[i].add(j);adj[j].add(i)
    live=set(range(m));canonical=[]
    while live:
        v=min(live,key=lambda i:(len(adj[i]&live),ordered[i]));nbr=adj[v]&live
        for i in nbr:adj[i].update(nbr-{i})
        live.remove(v);canonical.append(ordered[v])
    return np.array([1.,sum(s[a,b]!=0 for a,b in pairs),float(pairs==canonical)])

s=np.array([[0.0, 0.0], [0.0, 0.0]],dtype=float)
assert np.allclose(_ordering_metrics(s,paired_ordering(s)), target)

